import json, math, time
from pathlib import Path
import numpy as np

CONFIG_ID='iv-coupled-gd-v5-config-001'
MAX_ITERATIONS=3000
TOLERANCE=1e-4
RATES=[{'setting_id':'slow_interior','alpha':2e-5,'eta':5e-4},{'setting_id':'fast_interior_candidate','alpha':2e-4,'eta':3e-3},{'setting_id':'near_bound_candidate','alpha':5e-4,'eta':5e-3},{'setting_id':'beyond_bound_stress','alpha':3e-3,'eta':2e-2}]
SEEDS={50:[51001,51002,51003,51004],100:[101001,101002,101003,101004],150:[151001,151002,151003,151004]}
CHECKPOINTS=[0,10,50,100,250,500,1000,2000,3000]
METRICS=['beta_2sls_l2','beta_true_l2','beta_ols_l2','beta_2sls_true_l2']

def generate_data(rng,n,q=10,p=5,noise=1.0):
    Z=rng.normal(size=(n,q)); theta=rng.normal(size=(q,p)); beta=rng.normal(size=p)
    Phi=rng.normal(size=(p,p)); phi=rng.normal(size=p); U=rng.normal(size=(n,p))
    E2=rng.normal(size=(n,p)); E1=rng.normal(size=n)
    X=Z@theta+noise*(U@Phi)+E2; Y=X@beta+noise*(U@phi)+E1
    return Y,X,Z,beta,theta

def finite(x):
    x=float(x)
    return x if math.isfinite(x) else None

def norm(x): return finite(np.linalg.norm(x))

def cond_record(a):
    try: v=float(np.linalg.cond(a,2))
    except np.linalg.LinAlgError as e: return None,'linear_algebra_error: '+str(e)
    return (v,None) if math.isfinite(v) else (None,'non_finite_condition_number')

def build_config():
    reps=[]
    for n,seeds in SEEDS.items():
        for i,seed in enumerate(seeds,1): reps.append({'replicate_id':f'n{n}-r{i:02d}','seed':seed,'n':n})
    return {'schema_version':'iv-exp-config-1','config_id':CONFIG_ID,'method_id':'coupled-iv-gradient-frozen-old-state','dtype':'float64','n_values':[50,100,150],'p':5,'q':10,'noise':1.0,'rate_settings':RATES,'replicates':reps,'max_iterations':MAX_ITERATIONS,'tolerance':{'value':TOLERANCE,'metric':'beta_2sls_l2'},'stopping_rule':{'rule':'run every full-rank trajectory through the shared fixed budget; record first tolerance hit without early termination','shared_across_settings':True},'rank_policy':{'required':{'rank_Z':10,'rank_ZTheta_hat':5},'policy':'retain all samples; mark rank failures and do not replace them','failures_retained':True},'resource_budget':{'cpus':2,'memory_mb':2048,'disk_mb':1024,'wall_seconds':1200},'generator_source':'embedded exact copy of released assets/base_resources.py generate_data','generator_sha256':'c720367a63675508b59ad9cd066768e4d958cf9a97f9ce13982201af64067ea2','design_note':'Rates and seeds were declared before execution; bound membership is computed separately for every sample.'}

def prepare(rep):
    rng=np.random.default_rng(rep['seed'])
    y,x,z,beta_true,_=generate_data(rng,rep['n'],10,5,1.0)
    y=np.asarray(y,dtype=np.float64); x=np.asarray(x,dtype=np.float64); z=np.asarray(z,dtype=np.float64); beta_true=np.asarray(beta_true,dtype=np.float64)
    theta_hat=np.linalg.lstsq(z,x,rcond=None)[0]; projected=z@theta_hat
    beta_2sls=np.linalg.lstsq(projected,y,rcond=None)[0]; beta_ols=np.linalg.lstsq(x,y,rcond=None)[0]
    rz=int(np.linalg.matrix_rank(z)); rx=int(np.linalg.matrix_rank(x)); rp=int(np.linalg.matrix_rank(projected))
    cz,czr=cond_record(z); cx,cxr=cond_record(x); cp,cpr=cond_record(projected)
    sz=float(np.linalg.svd(z,compute_uv=False)[0]); sp=float(np.linalg.svd(projected,compute_uv=False)[0])
    return {'y':y,'x':x,'z':z,'beta_true':beta_true,'theta_hat':theta_hat,'beta_2sls':beta_2sls,'beta_ols':beta_ols,'full_rank':rz==10 and rp==5,'A_alpha':2/(sp*sp),'A_eta':2/(sz*sz),'rank_diagnostics':{'rank_Z':rz,'rank_X':rx,'rank_ZTheta_hat':rp,'condition_Z_2':cz,'condition_Z_2_reason':czr,'condition_X_2':cx,'condition_X_2_reason':cxr,'condition_ZTheta_hat_2':cp,'condition_ZTheta_hat_2_reason':cpr}}

def trajectory(rep,setting,s):
    start=time.perf_counter(); alpha=float(setting['alpha']); eta=float(setting['eta']); z=s['z']; y=s['y']; th=s['theta_hat']
    ga=float(np.max(np.abs(np.linalg.eigvalsh(np.eye(5)-alpha*(th.T@z.T@z@th)))))
    ke=float(np.max(np.abs(np.linalg.eigvalsh(np.eye(10)-eta*(z.T@z)))))
    result={'schema_version':'iv-exp-replicate-1','experiment_id':rep['replicate_id']+'--'+setting['setting_id'],'replicate_id':rep['replicate_id'],'config_id':CONFIG_ID,'setting_id':setting['setting_id'],'seed':rep['seed'],'n':rep['n'],'status':'completed' if s['full_rank'] else 'rank_deficient','rank_diagnostics':s['rank_diagnostics'],'rate_diagnostics':{'alpha':alpha,'eta':eta,'A_alpha':s['A_alpha'],'A_eta':s['A_eta'],'within_alpha_bound':0<alpha<s['A_alpha'],'within_eta_bound':0<eta<s['A_eta'],'gamma_alpha':finite(ga),'kappa_eta':finite(ke),'Lambda':finite(max(ga,ke))},'iterations':[],'stopping':{'reason':'fixed_budget_completed','stopped':False,'iteration':MAX_ITERATIONS,'first_tolerance_iteration':None},'execution':{'elapsed_wall_seconds':None,'configured_budget':{'wall_seconds':1200},'failure_reason':None}}
    theta=np.zeros((10,5),dtype=np.float64); beta=np.zeros(5,dtype=np.float64)
    ols_error=norm(s['beta_ols']-s['beta_true']); sls_error=norm(s['beta_2sls']-s['beta_true'])
    def record(t):
        d=norm(beta-s['beta_2sls'])
        result['iterations'].append({'t':t,'beta_2sls_l2':d,'beta_true_l2':norm(beta-s['beta_true']),'beta_ols_l2':ols_error,'beta_2sls_true_l2':sls_error,'theta_frobenius':norm(theta),'beta_finite':bool(np.all(np.isfinite(beta))),'theta_finite':bool(np.all(np.isfinite(theta)))})
        if d is not None and d<=TOLERANCE and result['stopping']['first_tolerance_iteration'] is None: result['stopping']['first_tolerance_iteration']=t
    record(0)
    if s['full_rank']:
        with np.errstate(over='ignore',invalid='ignore'):
            for t in range(MAX_ITERATIONS):
                old_theta=theta; old_beta=beta
                theta=old_theta-eta*(z.T@(z@old_theta-s['x']))
                beta=old_beta-alpha*(old_theta.T@z.T@(z@old_theta@old_beta-y))
                record(t+1)
                if not (np.all(np.isfinite(theta)) and np.all(np.isfinite(beta))):
                    result['status']='numerical_failure'; result['stopping']={'reason':'non_finite_state','stopped':True,'iteration':t+1,'first_tolerance_iteration':result['stopping']['first_tolerance_iteration']}; result['execution']['failure_reason']='non_finite_state'; break
    else:
        result['stopping']={'reason':'rank_policy_skip','stopped':True,'iteration':0,'first_tolerance_iteration':None}; result['execution']['failure_reason']='required_sample_rank_failed; retained without replacement'
    result['execution']['elapsed_wall_seconds']=float(time.perf_counter()-start)
    return result

def build_report(results,total):
    experiments=[{'experiment_id':r['experiment_id'],'setting_id':r['setting_id'],'replicate_id':r['replicate_id'],'seed':r['seed'],'n':r['n'],'status':r['status'],'artifact_paths':['config.json','replicate_results.jsonl']} for r in results]
    aggregates=[]; exclusions=[]
    for setting in RATES:
        for n in [50,100,150]:
            group=[r for r in results if r['setting_id']==setting['setting_id'] and r['n']==n]
            for t in CHECKPOINTS:
                for metric in METRICS:
                    vals=[]; ids=[]
                    for r in group:
                        if t<len(r['iterations']) and r['iterations'][t].get(metric) is not None:
                            vals.append(float(r['iterations'][t][metric])); ids.append(r['replicate_id'])
                        else: exclusions.append({'experiment_id':r['experiment_id'],'metric':metric,'iteration':t,'reason':'iteration_missing_or_metric_non_finite'})
                    aggregates.append({'setting_id':setting['setting_id'],'n':n,'metric':metric,'iteration':t,'independent_replicate_count':len(vals),'included_replicate_ids':ids,'mean':finite(np.mean(vals)) if vals else None,'median':finite(np.median(vals)) if vals else None})
    completed=[r for r in results if r['status']=='completed']
    inside=[r for r in completed if r['rate_diagnostics']['within_alpha_bound'] and r['rate_diagnostics']['within_eta_bound']]
    hits=[r for r in inside if r['stopping']['first_tolerance_iteration'] is not None]
    beyond=[r for r in completed if not (r['rate_diagnostics']['within_alpha_bound'] and r['rate_diagnostics']['within_eta_bound'])]
    misses=[r for r in beyond if r['stopping']['first_tolerance_iteration'] is None]
    paired=[r['iterations'][-1]['beta_true_l2']<r['iterations'][-1]['beta_2sls_true_l2'] for r in completed]
    h1='supported' if inside and len(hits)==len(inside) else ('not_supported' if inside else 'untested')
    h2='supported' if completed and misses else ('inconclusive' if completed else 'untested')
    h3='supported' if paired and not all(paired) else ('not_supported' if paired else 'untested')
    ids=[r['experiment_id'] for r in results]
    return {'schema_version':'iv-exp-report-1','config_id':CONFIG_ID,'experiments':experiments,'aggregates':aggregates,'hypotheses':[{'hypothesis_id':'H1','status':h1,'experiment_ids':[r['experiment_id'] for r in inside],'evidence_paths':['config.json','replicate_results.jsonl','report.json#/aggregates']},{'hypothesis_id':'H2','status':h2,'experiment_ids':ids,'evidence_paths':['config.json#/rate_settings','replicate_results.jsonl','report.json#/aggregates']},{'hypothesis_id':'H3','status':h3,'experiment_ids':ids,'evidence_paths':['replicate_results.jsonl','report.json#/aggregates']}],'conclusions':[{'statement':f'H1: {len(hits)} of {len(inside)} completed trajectories inside both sample-specific bounds reached beta_2sls_l2 <= {TOLERANCE} within {MAX_ITERATIONS} iterations.','uncertainty':'Finite deterministic outcomes for twelve independently seeded samples; no population-frequency claim.','limitations':'The asymptotic theorem does not guarantee this finite tolerance and budget.','evidence_paths':['replicate_results.jsonl','report.json#/aggregates']},{'statement':f'H2: {len(misses)} of {len(beyond)} completed beyond-bound trajectories missed the tolerance; complete trajectories document rate dependence.','uncertainty':'Descriptive comparison of four predeclared rate pairs, not a continuous response surface.','limitations':'Beyond-bound behavior is empirical, not a theorem prediction.','evidence_paths':['config.json#/rate_settings','replicate_results.jsonl','report.json#/aggregates']},{'statement':f'H3: final finite-iteration true-beta error was below sample-2SLS true-beta error in {sum(paired)} of {len(paired)} completed trajectories.','uncertainty':'Settings reuse samples and are paired trajectories, not independent runs across settings.','limitations':'Generated-beta error is simulation-specific; optimization tolerance is not statistical uncertainty.','evidence_paths':['replicate_results.jsonl','report.json#/aggregates']},{'statement':'Finite-sample ranks and this known generator do not establish population correlation assumptions or arbitrary-data claims.','uncertainty':'Scope qualification, not an estimate.','limitations':'CPU synthetic study only; no Transformer, GPU, or whole-paper claim.','evidence_paths':['config.json','experiment.py']}],'excluded_observations':exclusions,'execution_summary':{'total_wall_seconds':float(total),'trajectory_count':len(results),'completed_count':len(completed),'rank_deficient_count':sum(r['status']=='rank_deficient' for r in results),'numerical_failure_count':sum(r['status']=='numerical_failure' for r in results)}}

def validate(config,results,report):
    assert config['schema_version']=='iv-exp-config-1'
    assert len({r['replicate_id'] for r in config['replicates']})==len(config['replicates'])
    assert len({s['setting_id'] for s in config['rate_settings']})==len(config['rate_settings'])
    assert len(results)==len(config['replicates'])*len(config['rate_settings'])
    assert len({r['experiment_id'] for r in results})==len(results)
    assert len({(r['replicate_id'],r['setting_id']) for r in results})==len(results)
    reps={r['replicate_id']:r for r in config['replicates']}
    for r in results:
        assert r['seed']==reps[r['replicate_id']]['seed'] and r['n']==reps[r['replicate_id']]['n']
        assert [x['t'] for x in r['iterations']]==list(range(len(r['iterations'])))
        if r['status']=='completed': assert len(r['iterations'])==MAX_ITERATIONS+1
    assert {h['hypothesis_id'] for h in report['hypotheses']}=={'H1','H2','H3'}
    json.dumps(config,allow_nan=False); json.dumps(results,allow_nan=False); json.dumps(report,allow_nan=False)

def main():
    started=time.perf_counter(); config=build_config()
    samples={r['replicate_id']:prepare(r) for r in config['replicates']}
    results=[trajectory(r,s,samples[r['replicate_id']]) for r in config['replicates'] for s in RATES]
    report=build_report(results,time.perf_counter()-started); validate(config,results,report)
    Path('config.json').write_text(json.dumps(config,ensure_ascii=False,allow_nan=False,sort_keys=True,indent=2)+'\n',encoding='utf-8')
    Path('replicate_results.jsonl').write_text(''.join(json.dumps(r,ensure_ascii=False,allow_nan=False,sort_keys=True,separators=(',',':'))+'\n' for r in results),encoding='utf-8')
    Path('report.json').write_text(json.dumps(report,ensure_ascii=False,allow_nan=False,sort_keys=True,indent=2)+'\n',encoding='utf-8')
    print(json.dumps({'status':'completed','trajectory_count':len(results),'elapsed_wall_seconds':report['execution_summary']['total_wall_seconds']},allow_nan=False))

if __name__=='__main__': main()
